struct FeeParams {
    // Min zkp per utxo, divided by 1e12
    uint32 scPerUtxoReward;
    // Charged amount per kyt, divided by 1e12
    uint32 scPerKytFee;
    // Charged amount for kyc, divided by 1e12
    uint32 scKycFee;
